versions.variantCss:
.wemd-styled-table[data-variant="bytedance-table-clean"] {
  margin: 16px 0;
  background: var(--wemd-bg-card);
  border-radius: var(--wemd-border-radius);
  overflow: hidden;
  border: 1px solid var(--wemd-border-soft);
  box-shadow: var(--wemd-shadow);
}
.wemd-styled-table[data-variant="bytedance-table-clean"] .wemd-component-body {
  padding: 0;
}
.wemd-styled-table[data-variant="bytedance-table-clean"] .wemd-component-body .wemd-child-1 {
  background: var(--wemd-primary);
  color: #ffffff;
  font-size: 14px;
  font-weight: 700;
  padding: 12px 16px;
  margin: 0;
}
.wemd-styled-table[data-variant="bytedance-table-clean"] .wemd-component-body .wemd-child-2,
.wemd-styled-table[data-variant="bytedance-table-clean"] .wemd-component-body .wemd-child-3,
.wemd-styled-table[data-variant="bytedance-table-clean"] .wemd-component-body .wemd-child-4 {
  color: var(--wemd-text-normal);
  font-size: 14px;
  padding: 12px 16px;
  margin: 0;
  border-bottom: 1px solid var(--wemd-border-soft);
}
